import { lazy } from 'react'

import { ImageWithComment, Period, Remarks, stackSheetsStyle } from '~/ui/layout/item/explanation'
import { HowToCraft } from '~/ui/items/common/mindOfInstructions'

import usageMethod01 from './explanation/01-01.method.jpg'
import usageMethod02 from './explanation/01-02.method.jpg'
import usageMethod03 from './explanation/01-03.method.jpg'
import usageMethod04 from './explanation/01-04.method.jpg'


const RatchetMechanismLink = lazy(() => import('~/ui/items/block/lego/method/ratchetMechanism/Link'));
const BeltTransmissionLink = lazy(() => import('~/ui/items/block/lego/method/beltTransmission/Link'));
const ConnectPattern02Link = lazy(() => import('~/ui/items/block/lego/method/connectPattern02/Link'));
const ConnectPattern03Link = lazy(() => import('~/ui/items/block/lego/method/connectPattern03/Link'));



type ExplanationProp = {
  openDrawer: (kind: string, name: string) => () => void;
}
export default function Explanation(prop: ExplanationProp) {
  const { openDrawer } = prop;
  
  return (
    <>
      <Period lemma='作り方 ＆ 思い付いたキッカケ：'>
        <HowToCraft />
        <ImageWithComment image={usageMethod01} contentAspectRatio='3 / 4' commentMinWidth='20em' css={stackSheetsStyle}>
          ハンドルを回すとゼンマイが巻かれて(巻いている間はホールが動かない)、ハンドルを放すとホールが回転する部分。<br/>
          ここは<RatchetMechanismLink openDrawer={openDrawer} />を使ってます。<br/>
          <Remarks mark='※'>
            ゼンマイの動力で最初に思い付いたのが "ゼンマイで回転するメリーゴーランド" だったことが作ったキッカケです
          </Remarks>
        </ImageWithComment>
        <br/>
        <ImageWithComment image={usageMethod02} contentAspectRatio='3 / 4' commentMinWidth='20em' css={stackSheetsStyle}>
          レゴの人２組がそれぞれ反対方向に回転しつつダンスをする部分。<br/>
          ここは<BeltTransmissionLink openDrawer={openDrawer} />を使ってます。<br/>
        </ImageWithComment>
        <br/>
        <ImageWithComment image={usageMethod03} contentAspectRatio='3 / 4' commentMinWidth='20em' css={stackSheetsStyle}>
          クネクネした木っぽいブロックで天板を支えたり、レゴの人を車輪に固定したりしてる部分。<br/>
          ここは<ConnectPattern03Link openDrawer={openDrawer} />、<ConnectPattern02Link openDrawer={openDrawer} />で紹介しているブロックの組み方で作ってます。<br/>
        </ImageWithComment>
        <br/>
        <ImageWithComment image={usageMethod04} contentAspectRatio='3 / 4' commentMinWidth='20em' css={stackSheetsStyle}>
          一番上でちょっと遅れて回転している部分。<br/>
          ここは敢えてくっつけず、歯車で回る軸(じく)の上に乗せただけとしてます。<br/>
          こうすると "流体ギア" のように歯車の回転が伝わって回転するのでちょっと面白いかと思って作ってみました<br/>
          <Remarks mark='※'>
            間に液体がないので、"流体ギア" とは言えないのですが、仕組みがちょっと似ていて連想したので、そのように表現しました。興味を持ってもらえたら嬉しいです。
          </Remarks>
        </ImageWithComment>
        <br/>
        これらを組み合わせて、あとはデコレーションしたら完成です。<br/>
        (ここでは南国レジャーのオープンダンスホールをイメージ。「こうしたらそれっぽいかな」と先入観多目ですが)
      </Period>
    </>
  )
}

